create extension if not exists pgcrypto;
create type public.user_role as enum ('user','admin');
create type public.account_status as enum ('active','blocked');
create type public.submission_status as enum ('pending','approved','rejected');
create type public.withdrawal_status as enum ('pending','approved','rejected');
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',email text not null,role user_role not null default 'user',wallet_balance bigint not null default 0 check(wallet_balance>=0),account_status account_status not null default 'active',avatar_url text,created_at timestamptz not null default now());
create table if not exists public.email_submissions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,email_addresses text[] not null, status submission_status not null default 'pending',rejection_reason text,reward_amount bigint not null default 0,created_at timestamptz not null default now(),reviewed_at timestamptz,reviewed_by uuid references public.profiles(id));
create table if not exists public.withdrawals(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,wallet_name text not null,wallet_number text not null,amount bigint not null check(amount>0),admin_fee bigint not null default 0,net_amount bigint not null,status withdrawal_status not null default 'pending',rejection_reason text,created_at timestamptz not null default now(),processed_at timestamptz,processed_by uuid references public.profiles(id));
create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,type text not null check(type in('reward','withdrawal','refund','adjustment')),amount bigint not null,description text not null,reference_id uuid,created_at timestamptz not null default now());
create table if not exists public.system_settings(setting_key text primary key,setting_value jsonb not null, is_public boolean not null default true,updated_at timestamptz not null default now(),updated_by uuid references public.profiles(id));
create table if not exists public.announcements(id uuid primary key default gen_random_uuid(),title text not null,content text not null,is_active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_by uuid references public.profiles(id));
create table if not exists public.admin_audit_logs(id uuid primary key default gen_random_uuid(),admin_id uuid not null references public.profiles(id),action text not null,entity_type text,entity_id uuid,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists email_submissions_user_status_idx on public.email_submissions(user_id,status,created_at desc);create index if not exists withdrawals_user_status_idx on public.withdrawals(user_id,status,created_at desc);create index if not exists transactions_user_idx on public.transactions(user_id,created_at desc);create unique index if not exists email_submission_addresses_idx on public.email_submissions using gin(email_addresses);
insert into public.system_settings(setting_key,setting_value) values ('reward_per_email','4000'),('minimum_withdrawal','25000'),('withdrawal_fee','0'),('deposit_limit','50'),('deposit_enabled','true'),('withdraw_enabled','true'),('whatsapp_support','""'),('telegram_support','""') on conflict do nothing;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='admin' and account_status='active'); $$;
create or replace function public.submit_email_addresses(p_emails text[]) returns uuid language plpgsql security definer set search_path=public as $$ declare id uuid; limit_count int; begin if auth.uid() is null then raise exception 'Login diperlukan'; end if; select coalesce((setting_value #>> '{}')::int,50) into limit_count from system_settings where setting_key='deposit_limit'; if coalesce(array_length(p_emails,1),0)=0 or array_length(p_emails,1)>limit_count then raise exception 'Jumlah email melewati limit'; end if; if exists(select 1 from email_submissions s where s.user_id=auth.uid() and s.status='pending' and s.email_addresses && p_emails) then raise exception 'Email sudah ada di pengajuan pending'; end if; insert into email_submissions(user_id,email_addresses) values(auth.uid(),p_emails) returning email_submissions.id into id; return id; end $$;
create or replace function public.create_withdrawal(p_amount bigint,p_wallet_name text,p_wallet_number text) returns uuid language plpgsql security definer set search_path=public as $$ declare id uuid; fee bigint; minimum bigint; begin if auth.uid() is null then raise exception 'Login diperlukan'; end if; select coalesce((select (setting_value #>> '{}')::bigint from system_settings where setting_key='minimum_withdrawal'),0),coalesce((select (setting_value #>> '{}')::bigint from system_settings where setting_key='withdrawal_fee'),0) into minimum,fee; if p_amount<minimum then raise exception 'Nominal di bawah minimum penarikan'; end if; update profiles set wallet_balance=wallet_balance-p_amount where id=auth.uid() and wallet_balance>=p_amount returning id into id; if id is null then raise exception 'Saldo tidak mencukupi'; end if; insert into withdrawals(user_id,wallet_name,wallet_number,amount,admin_fee,net_amount) values(auth.uid(),p_wallet_name,p_wallet_number,p_amount,fee,p_amount-fee) returning withdrawals.id into id; return id; end $$;
create or replace function public.approve_submission(p_submission_id uuid,p_reason text default null) returns void language plpgsql security definer set search_path=public as $$ declare s email_submissions; reward bigint; begin if not is_admin() then raise exception 'Akses admin ditolak'; end if; select * into s from email_submissions where id=p_submission_id for update; if s.status<>'pending' then raise exception 'Pengajuan sudah diproses'; end if; select coalesce((setting_value #>> '{}')::bigint,0) into reward from system_settings where setting_key='reward_per_email'; reward:=reward*coalesce(array_length(s.email_addresses,1),0); update email_submissions set status='approved',reward_amount=reward,reviewed_at=now(),reviewed_by=auth.uid() where id=s.id; update profiles set wallet_balance=wallet_balance+reward where id=s.user_id; insert into transactions(user_id,type,amount,description,reference_id) values(s.user_id,'reward',reward,'Reward setoran email',s.id); insert into admin_audit_logs(admin_id,action,entity_type,entity_id) values(auth.uid(),'approve','email_submission',s.id); end $$;
create or replace function public.reject_submission(p_submission_id uuid,p_reason text) returns void language plpgsql security definer set search_path=public as $$ begin if not is_admin() then raise exception 'Akses admin ditolak'; end if; update email_submissions set status='rejected',rejection_reason=coalesce(p_reason,'Tidak disebutkan'),reviewed_at=now(),reviewed_by=auth.uid() where id=p_submission_id and status='pending'; if not found then raise exception 'Pengajuan sudah diproses'; end if; insert into admin_audit_logs(admin_id,action,entity_type,entity_id,details) values(auth.uid(),'reject','email_submission',p_submission_id,jsonb_build_object('reason',p_reason)); end $$;
create or replace function public.approve_withdrawal(p_withdrawal_id uuid,p_reason text default null) returns void language plpgsql security definer set search_path=public as $$ begin if not is_admin() then raise exception 'Akses admin ditolak'; end if; update withdrawals set status='approved',processed_at=now(),processed_by=auth.uid() where id=p_withdrawal_id and status='pending'; if not found then raise exception 'Penarikan sudah diproses'; end if; insert into transactions(user_id,type,amount,description,reference_id) select user_id,'withdrawal',-amount,'Penarikan disetujui',id from withdrawals where id=p_withdrawal_id; insert into admin_audit_logs(admin_id,action,entity_type,entity_id) values(auth.uid(),'approve','withdrawal',p_withdrawal_id); end $$;
create or replace function public.reject_withdrawal(p_withdrawal_id uuid,p_reason text) returns void language plpgsql security definer set search_path=public as $$ declare w withdrawals; begin if not is_admin() then raise exception 'Akses admin ditolak'; end if; update withdrawals set status='rejected',rejection_reason=coalesce(p_reason,'Tidak disebutkan'),processed_at=now(),processed_by=auth.uid() where id=p_withdrawal_id and status='pending' returning * into w; if w.id is null then raise exception 'Penarikan sudah diproses'; end if; update profiles set wallet_balance=wallet_balance+w.amount where id=w.user_id; insert into transactions(user_id,type,amount,description,reference_id) values(w.user_id,'refund',w.amount,'Refund penarikan ditolak',w.id); insert into admin_audit_logs(admin_id,action,entity_type,entity_id,details) values(auth.uid(),'reject','withdrawal',w.id,jsonb_build_object('reason',p_reason)); end $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,email) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.email); return new; end $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table profiles enable row level security;alter table email_submissions enable row level security;alter table withdrawals enable row level security;alter table transactions enable row level security;alter table system_settings enable row level security;alter table announcements enable row level security;alter table admin_audit_logs enable row level security;
drop policy if exists profiles_self on profiles;create policy profiles_self on profiles for select using(id=auth.uid() or is_admin());drop policy if exists submissions_self on email_submissions;create policy submissions_self on email_submissions for select using(user_id=auth.uid() or is_admin());drop policy if exists withdrawals_self on withdrawals;create policy withdrawals_self on withdrawals for select using(user_id=auth.uid() or is_admin());drop policy if exists transactions_self on transactions;create policy transactions_self on transactions for select using(user_id=auth.uid() or is_admin());drop policy if exists settings_read on system_settings;create policy settings_read on system_settings for select using(is_public or is_admin());drop policy if exists settings_admin_write on system_settings;create policy settings_admin_write on system_settings for all using(is_admin()) with check(is_admin());drop policy if exists announcements_read on announcements;create policy announcements_read on announcements for select using(is_active or is_admin());drop policy if exists announcements_admin_write on announcements;create policy announcements_admin_write on announcements for all using(is_admin()) with check(is_admin());drop policy if exists audit_admin_read on admin_audit_logs;create policy audit_admin_read on admin_audit_logs for select using(is_admin());
